def sha(data):
    return hashlib.sha256(data).hexdigest()

def json_value(value):
    if isinstance(value, bytes):
        return value.decode('utf-8')
    if isinstance(value, (list, tuple)):
        return [json_value(v) for v in value]
    if isinstance(value, dict):
        return {json_value(k): json_value(v) for k, v in value.items()}
    return value

def canonical(value):
    return json.dumps(json_value(value), ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')

def write(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(json_value(value), ensure_ascii=False, sort_keys=True, indent=2) + '\n', encoding='utf-8')

