    owned = str(root / filename)
    assert first.startswith(prefix + owned + ' (') and first.count(owned) == 1
    return (first.replace(owned, '<clone>/' + filename, 1) + sep + rest).encode('utf-8')

def summary_line(candidate, parsed, limit=500):
    selected = min(candidate, limit)
    if candidate <= limit:
        return b''
    skipped = selected - parsed
    extra = f'{skipped} selected files were not parsed. ' if skipped else ''
    return (f'scan: Python analysis incomplete: parsed {parsed} of {candidate} candidate files; selected {selected} (limit {limit}), omitted {candidate-selected}. ' + extra + 'Missing signals may be in unanalysed files.\n').encode('utf-8')

